// 2 Zeilen, 3 Spalten
int[,] tabelle =
{
    { 1, 2, 3 },
    { 4, 5, 6 }
};

Console.WriteLine(tabelle[0, 2]);   // Zeile 0, Spalte 2 -> 3
Console.WriteLine(tabelle[1, 0]);   // Zeile 1, Spalte 0 -> 4

tabelle[1, 1] = 50;
Console.WriteLine(tabelle[1, 1]);   // 50

int[,] punkte =
{
    { 18, 20, 15, 19 },   // Ali
    { 12, 14, 16, 10 },   // Bea
    { 20, 19, 20, 18 }    // Cem
};
string[] namen = { "Ali", "Bea", "Cem" };

for (int z = 0; z < punkte.GetLength(0); z++)
{
    int summe = 0;
    for (int s = 0; s < punkte.GetLength(1); s++)
    {
        summe += punkte[z, s];
    }
    Console.WriteLine($"{namen[z]}: {summe} Punkte");
}
// Ausgabe:
// Ali: 72 Punkte
// Bea: 52 Punkte
// Cem: 77 Punkte

char[,] spiel =
{
    { 'X', 'O', '.' },
    { '.', 'X', 'O' },
    { '.', '.', 'X' }
};

for (int z = 0; z < 3; z++)
{
    for (int s = 0; s < 3; s++)
    {
        Console.Write(spiel[z, s] + " ");
    }
    Console.WriteLine();
}
// Ausgabe:
// X O .
// . X O
// . . X

int[][] noten = new int[3][];
noten[0] = new int[] { 1, 2 };        // Mathe: 2 Noten
noten[1] = new int[] { 3, 2, 1 };     // Deutsch: 3 Noten
noten[2] = new int[] { 2 };           // Englisch: 1 Note

Console.WriteLine(noten[1][0]);        // 3
Console.WriteLine(noten.Length);       // 3 Fächer
Console.WriteLine(noten[1].Length);    // 3 Noten in Deutsch

foreach (int[] fach in noten)
{
    Console.WriteLine(string.Join(" ", fach));
}
// Ausgabe der Schleife:
// 1 2
// 3 2 1
// 2

